questionvariables.text:
/* Fixed. Correct options third and fifth (not first: kit option-order rule). */
ta1: [
 [bad_every, false, "Then \\(n = 2k + 1\\) for every integer \\(k\\)."],
 [bad_one, false, "Then \\(n = 2k + 1\\), where \\(k = 1\\)."],
 [ok_plus, true, "Then \\(n = 2k + 1\\) for some integer \\(k\\)."],
 [bad_concl, false, "Then \\(n^2 - 1 = 8k\\) for some integer \\(k\\)."],
 [ok_minus, true, "Then \\(n = 2k - 1\\) for some integer \\(k\\)."]
];

feedbackvariables.text:
sel: setify(ans1);
hev: if elementp(bad_every, sel) then 1 else 0;
hone: if elementp(bad_one, sel) then 1 else 0;
hcon: if elementp(bad_concl, sel) then 1 else 0;
